/**
 * Laptop Price Dataset - Interactive Dashboard & Real-time Predictor
 * Client-side script: parses data/results.json, updates KPIs, renders Chart.js charts,
 * manages tab switching, and executes real-time linear regression inference.
 */

let globalData = null;
let stepwiseChart = null;
let scatterChart = null;
let residualChart = null;

// Initialize on DOM load
document.addEventListener('DOMContentLoaded', () => {
    loadDashboardData();
    setupEventListeners();
});

/**
 * Fetch results.json generated by scripts/build_results.py
 */
async function loadDashboardData() {
    try {
        const response = await fetch('data/results.json');
        if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
        }
        globalData = await response.json();
        
        // Render components
        renderKPIs(globalData.summary_metrics);
        renderFeatureMapping(globalData.feature_mapping);
        renderStepwiseChart(globalData.stepwise_evaluation, globalData.summary_metrics.best_cv_k);
        renderStepwiseTable(globalData.stepwise_evaluation, globalData.summary_metrics);
        renderFeatureSelectionTabs(globalData.feature_selection_methods);
        initPredictor(globalData.model_parameters);
        renderVerificationSamples(globalData.verification_samples);
        renderScatterAndResiduals(globalData.scatter_data);
        
    } catch (err) {
        console.error('Failed to load results.json:', err);
        const warning = document.createElement('div');
        warning.style.padding = '20px';
        warning.style.background = 'rgba(239, 68, 68, 0.2)';
        warning.style.border = '1px solid #ef4444';
        warning.style.borderRadius = '8px';
        warning.style.margin = '20px 0';
        warning.style.color = '#fca5a5';
        warning.innerHTML = `<strong>⚠️ 資料載入失敗：</strong> 請確認是否已執行 <code>python scripts/build_results.py</code> 產生 <code>data/results.json</code>。<br><small>${err.message}</small>`;
        document.querySelector('.container').prepend(warning);
    }
}

/**
 * 1. 摘要指標卡 (KPIs)
 */
function renderKPIs(metrics) {
    document.getElementById('kpiTotalSamples').textContent = Number(metrics.total_samples).toLocaleString() + ' 筆';
    document.getElementById('kpiTotalSamplesSub').textContent = `訓練集 ${metrics.train_samples} 筆 · 測試集 ${metrics.test_samples} 筆 (80/20)`;

    document.getElementById('kpiRawFeatures').textContent = metrics.raw_columns_count + ' 欄';
    document.getElementById('kpiRawFeaturesSub').textContent = '剔除 ID 與高基數 Product 後特徵工程';

    document.getElementById('kpiEncodedFeatures').textContent = metrics.encoded_features_count + ' 個';
    document.getElementById('kpiEncodedFeaturesSub').textContent = '9 數值特徵 + 29 One-Hot 編碼欄位';

    document.getElementById('kpiCvBest').textContent = `k=${metrics.best_cv_k}`;
    document.getElementById('kpiCvBestSub').textContent = `5-Fold CV 訓練集 RMSE: €${metrics.best_cv_rmse}`;

    document.getElementById('kpiTestRmse').textContent = `€${metrics.best_cv_test_rmse}`;
    document.getElementById('kpiTestRmseSub').textContent = `測試集 MAE: €${metrics.best_cv_test_mae}`;

    document.getElementById('kpiTestR2').textContent = metrics.best_cv_test_r2;
    document.getElementById('kpiTestR2Sub').textContent = `解釋力 ${(metrics.best_cv_test_r2 * 100).toFixed(1)}% (261 筆測試樣本)`;
}

/**
 * 2. 原始欄位 → 特徵工程 → One-Hot Encoding 對照表
 */
function renderFeatureMapping(mapping) {
    const tbody = document.getElementById('featureMappingBody');
    if (!tbody) return;
    tbody.innerHTML = '';

    mapping.forEach(item => {
        const tr = document.createElement('tr');
        
        const badgeClass = item.encoded_count === 0 ? 'badge-gray' : (item.encoded_count > 3 ? 'badge-purple' : 'badge-blue');
        
        tr.innerHTML = `
            <td><code>${item.raw_column}</code></td>
            <td><span class="badge-tag badge-blue">${item.role}</span></td>
            <td>${item.treatment}</td>
            <td><strong style="color: #38bdf8;">${item.encoded_count}</strong></td>
            <td>${item.features.map(f => `<span class="badge-tag ${badgeClass}">${f}</span>`).join(' ') || '<span style="color:var(--text-muted)">無 (未納入模型)</span>'}</td>
        `;
        tbody.appendChild(tr);
    });
}

/**
 * 3. 雙折線趨勢圖 (Chart.js)
 */
function renderStepwiseChart(stepwiseData, bestCvK) {
    const ctx = document.getElementById('stepwiseChart');
    if (!ctx) return;

    const labels = stepwiseData.map(d => `k=${d.k}`);
    const cvRmseData = stepwiseData.map(d => d.cv_rmse);
    const testRmseData = stepwiseData.map(d => d.test_rmse);
    const testR2Data = stepwiseData.map(d => d.test_r2);

    if (stepwiseChart) {
        stepwiseChart.destroy();
    }

    stepwiseChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [
                {
                    label: '訓練集 5-Fold CV RMSE (€)',
                    data: cvRmseData,
                    borderColor: '#06b6d4',
                    backgroundColor: 'rgba(6, 182, 212, 0.15)',
                    tension: 0.25,
                    borderWidth: 2.5,
                    pointRadius: stepwiseData.map(d => d.k === bestCvK ? 7 : 3),
                    pointHoverRadius: 8,
                    pointBackgroundColor: stepwiseData.map(d => d.k === bestCvK ? '#10b981' : '#06b6d4'),
                    pointBorderColor: '#fff',
                    yAxisID: 'y'
                },
                {
                    label: '測試集 RMSE (€)',
                    data: testRmseData,
                    borderColor: '#f59e0b',
                    backgroundColor: 'rgba(245, 158, 11, 0.1)',
                    tension: 0.25,
                    borderWidth: 2,
                    pointRadius: 3,
                    pointHoverRadius: 6,
                    yAxisID: 'y'
                },
                {
                    label: '測試集 R² (決定係數)',
                    data: testR2Data,
                    borderColor: '#a855f7',
                    backgroundColor: 'rgba(168, 85, 247, 0.1)',
                    tension: 0.25,
                    borderWidth: 2,
                    borderDash: [5, 4],
                    pointRadius: 3,
                    pointHoverRadius: 6,
                    yAxisID: 'y1'
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            interaction: {
                mode: 'index',
                intersect: false
            },
            plugins: {
                legend: {
                    position: 'top',
                    labels: {
                        color: '#94a3b8',
                        font: { family: "'Plus Jakarta Sans', sans-serif", size: 12 },
                        usePointStyle: true
                    }
                },
                tooltip: {
                    backgroundColor: 'rgba(15, 23, 42, 0.95)',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    borderWidth: 1,
                    titleColor: '#fff',
                    bodyColor: '#cbd5e1',
                    padding: 12,
                    callbacks: {
                        afterTitle: (items) => {
                            const k = items[0].dataIndex + 1;
                            const rec = stepwiseData[k - 1];
                            return `最新加入特徵: ${rec.features[rec.features.length - 1]}`;
                        }
                    }
                }
            },
            scales: {
                x: {
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8', font: { size: 11 } }
                },
                y: {
                    type: 'linear',
                    position: 'left',
                    title: {
                        display: true,
                        text: 'RMSE (€ 越低越好)',
                        color: '#06b6d4',
                        font: { weight: 'bold' }
                    },
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#94a3b8' }
                },
                y1: {
                    type: 'linear',
                    position: 'right',
                    title: {
                        display: true,
                        text: 'R² 決定係數 (越高越好)',
                        color: '#a855f7',
                        font: { weight: 'bold' }
                    },
                    min: 0.4,
                    max: 0.85,
                    grid: { drawOnChartArea: false },
                    ticks: { color: '#a855f7' }
                }
            }
        }
    });
}

/**
 * 4. 特徵數量逐步評估結果詳細表
 */
function renderStepwiseTable(stepwiseData, metrics) {
    const tbody = document.getElementById('stepwiseTableBody');
    if (!tbody) return;
    tbody.innerHTML = '';

    stepwiseData.forEach(row => {
        const tr = document.createElement('tr');
        const isCvBest = (row.k === metrics.best_cv_k);
        const isTestBest = (row.k === metrics.best_test_k);

        if (isCvBest) {
            tr.classList.add('row-optimal');
        }

        const latestFeature = row.features[row.features.length - 1];
        
        let statusBadge = '';
        if (isCvBest) {
            statusBadge = '<span class="badge-tag badge-green" style="font-weight:700;">⭐ CV 最佳</span>';
        } else if (isTestBest) {
            statusBadge = '<span class="badge-tag badge-blue">🎯 測試最低</span>';
        }

        tr.innerHTML = `
            <td><strong>k = ${row.k}</strong> ${statusBadge}</td>
            <td>
                <span class="badge-tag badge-blue">${latestFeature}</span>
                <span style="font-size: 11px; color: var(--text-muted);">${row.features_display}</span>
            </td>
            <td><strong>€${row.cv_rmse}</strong></td>
            <td>€${row.test_rmse}</td>
            <td>€${row.test_mae}</td>
            <td><strong>${row.test_r2}</strong></td>
        `;
        tbody.appendChild(tr);
    });
}

/**
 * 5. 三種特徵選擇方法切換 (ANOVA, RFE, LassoCV)
 */
function renderFeatureSelectionTabs(methods) {
    // 1. ANOVA
    const anovaBody = document.getElementById('anovaTableBody');
    if (anovaBody) {
        anovaBody.innerHTML = '';
        methods.anova.forEach(item => {
            const tr = document.createElement('tr');
            tr.innerHTML = `
                <td><strong>#${item.rank}</strong></td>
                <td><span class="badge-tag badge-blue">${item.feature}</span></td>
                <td><strong style="color: #38bdf8;">${item.f_score.toLocaleString()}</strong></td>
                <td><span style="font-family: var(--font-mono); color: #a855f7;">${item.p_value}</span></td>
                <td>${item.description}</td>
            `;
            anovaBody.appendChild(tr);
        });
    }

    // 2. RFE
    const rfeBody = document.getElementById('rfeTableBody');
    if (rfeBody) {
        rfeBody.innerHTML = '';
        methods.rfe.forEach(item => {
            const tr = document.createElement('tr');
            const isTop = item.rank <= 10;
            tr.innerHTML = `
                <td><strong>#${item.rank}</strong></td>
                <td><span class="badge-tag ${isTop ? 'badge-green' : 'badge-gray'}">${item.feature}</span></td>
                <td>${item.rfe_rank === 1 ? '<span class="badge-tag badge-green">最優選定 (Rank 1)</span>' : `淘汰順序 ${item.rfe_rank}`}</td>
                <td>${item.description}</td>
            `;
            rfeBody.appendChild(tr);
        });
    }

    // 3. LassoCV
    const lassoBody = document.getElementById('lassoTableBody');
    const lassoAlphaEl = document.getElementById('lassoAlphaVal');
    if (lassoAlphaEl) {
        lassoAlphaEl.textContent = `最佳正則化強度 α = ${methods.lasso.alpha}`;
    }

    if (lassoBody) {
        lassoBody.innerHTML = '';
        methods.lasso.features.forEach(item => {
            const tr = document.createElement('tr');
            const badgeClass = item.is_selected ? (item.coef_standardized > 0 ? 'badge-green' : 'badge-purple') : 'badge-gray';
            tr.innerHTML = `
                <td><strong>#${item.rank}</strong></td>
                <td><span class="badge-tag ${badgeClass}">${item.feature}</span></td>
                <td><strong style="color: ${item.coef_standardized > 0 ? '#34d399' : (item.coef_standardized < 0 ? '#f43f5e' : '#64748b')}">${item.coef_standardized > 0 ? '+' : ''}${item.coef_standardized}</strong></td>
                <td>${item.abs_coef}</td>
                <td>${item.is_selected ? '<span style="color:#34d399; font-weight:600;">保留</span>' : '<span style="color:#94a3b8;">收縮歸零 (剔除)</span>'}</td>
                <td>${item.description}</td>
            `;
            lassoBody.appendChild(tr);
        });
    }
}

/**
 * 6. 即時筆電價格預測器 (Real-time Predictor)
 */
function initPredictor(model) {
    if (!model) return;

    // Populate Company dropdown
    const brandSelect = document.getElementById('predCompany');
    if (brandSelect && brandSelect.options.length <= 1) {
        brandSelect.innerHTML = '';
        model.top_companies.forEach(comp => {
            const opt = document.createElement('option');
            opt.value = comp;
            opt.textContent = comp;
            brandSelect.appendChild(opt);
        });
        const otherOpt = document.createElement('option');
        otherOpt.value = 'Other';
        otherOpt.textContent = '其他品牌 (Other)';
        brandSelect.appendChild(otherOpt);
        brandSelect.value = 'Dell';
    }

    // Bind change events to all inputs
    const inputs = document.querySelectorAll('.predictor-input');
    inputs.forEach(el => {
        el.addEventListener('input', updatePrediction);
        el.addEventListener('change', updatePrediction);
    });

    // Quick Presets
    document.querySelectorAll('.preset-chip').forEach(chip => {
        chip.addEventListener('click', () => {
            applyPreset(chip.getAttribute('data-preset'));
        });
    });

    // Run initial prediction
    updatePrediction();
}

/**
 * 計算價格預測
 */
function updatePrediction() {
    if (!globalData || !globalData.model_parameters) return;

    const model = globalData.model_parameters;
    const coefs = model.coefficients;
    const intercept = model.intercept;

    // Collect values
    const company = document.getElementById('predCompany').value;
    const typeName = document.getElementById('predTypeName').value;
    const inches = parseFloat(document.getElementById('predInches').value) || 15.6;
    const resValue = document.getElementById('predResolution').value;
    const isTouch = document.querySelector('input[name="predTouch"]:checked').value === '1' ? 1 : 0;
    const isIps = document.querySelector('input[name="predIps"]:checked').value === '1' ? 1 : 0;
    const ram = parseInt(document.getElementById('predRam').value, 10) || 8;
    const ssd = parseInt(document.getElementById('predSsd').value, 10) || 256;
    const hdd = parseInt(document.getElementById('predHdd').value, 10) || 0;
    const cpuType = document.getElementById('predCpuType').value;
    const cpuSpeed = parseFloat(document.getElementById('predCpuSpeed').value) || 2.5;
    const gpuBrand = document.getElementById('predGpuBrand').value;
    const opsys = document.getElementById('predOpSys').value;
    const weight = parseFloat(document.getElementById('predWeight').value) || 2.0;

    // Display hints
    document.getElementById('hintInches').textContent = `${inches.toFixed(1)}"`;
    document.getElementById('hintCpuSpeed').textContent = `${cpuSpeed.toFixed(1)} GHz`;
    document.getElementById('hintWeight').textContent = `${weight.toFixed(2)} kg`;

    // Calculate PPI
    let resW = 1920, resH = 1080;
    if (resValue === '1366x768') { resW = 1366; resH = 768; }
    else if (resValue === '1920x1080') { resW = 1920; resH = 1080; }
    else if (resValue === '2560x1440') { resW = 2560; resH = 1440; }
    else if (resValue === '3840x2160') { resW = 3840; resH = 2160; }
    const ppi = Math.round(((Math.sqrt(resW * resW + resH * resH)) / inches) * 100) / 100;
    document.getElementById('hintPpi').textContent = `${ppi.toFixed(1)} PPI`;

    // Map to dummy encoded features
    const featVals = {
        'Ram_GB': ram,
        'Weight_kg': weight,
        'Inches': inches,
        'PPI': ppi,
        'Cpu_Speed_GHz': cpuSpeed,
        'SSD_GB': ssd,
        'HDD_GB': hdd,
        'Touchscreen': isTouch,
        'IPS': isIps
    };

    const compClean = model.top_companies.includes(company) ? company : 'Other';
    model.ohe_categories.Company_Clean.forEach(c => {
        featVals[`Company_Clean_${c}`] = (compClean === c) ? 1 : 0;
    });

    model.ohe_categories.TypeName.forEach(t => {
        featVals[`TypeName_${t}`] = (typeName === t) ? 1 : 0;
    });

    model.ohe_categories.Cpu_Type.forEach(cp => {
        featVals[`Cpu_Type_${cp}`] = (cpuType === cp) ? 1 : 0;
    });

    model.ohe_categories.Gpu_Brand.forEach(g => {
        featVals[`Gpu_Brand_${g}`] = (gpuBrand === g) ? 1 : 0;
    });

    model.ohe_categories.OpSys_Clean.forEach(o => {
        featVals[`OpSys_Clean_${o}`] = (opsys === o) ? 1 : 0;
    });

    // Execute linear model formula
    let pred = intercept;
    let topPositiveContributors = [];
    let topNegativeContributors = [];

    model.final_features.forEach(feat => {
        const coef = coefs[feat] || 0;
        const val = featVals[feat] || 0;
        const contrib = coef * val;
        pred += contrib;

        if (val !== 0) {
            if (contrib > 0) {
                topPositiveContributors.push({ feat, contrib });
            } else if (contrib < 0) {
                topNegativeContributors.push({ feat, contrib });
            }
        }
    });

    // Floor at reasonable minimum laptop price
    const finalPrice = Math.max(120, pred);
    const twdRate = 34.5;
    const twdPrice = Math.round(finalPrice * twdRate);

    // Update UI
    document.getElementById('predictedPrice').textContent = finalPrice.toFixed(2);
    document.getElementById('predictedPriceTwd').textContent = `約合 NT$ ${twdPrice.toLocaleString()}`;

    // Top drivers display
    topPositiveContributors.sort((a, b) => b.contrib - a.contrib);
    topNegativeContributors.sort((a, b) => a.contrib - b.contrib);

    const posEl = document.getElementById('topPosDrivers');
    if (posEl) {
        posEl.innerHTML = topPositiveContributors.slice(0, 3)
            .map(c => `<li><span style="color:#34d399;">+€${c.contrib.toFixed(1)}</span> (${c.feat})</li>`)
            .join('') || '<li>無顯著加分項</li>';
    }

    const negEl = document.getElementById('topNegDrivers');
    if (negEl) {
        negEl.innerHTML = topNegativeContributors.slice(0, 2)
            .map(c => `<li><span style="color:#f43f5e;">-€${Math.abs(c.contrib).toFixed(1)}</span> (${c.feat})</li>`)
            .join('') || '<li>無顯著扣分項</li>';
    }

    // Warnings for anomalous combinations
    const warningBanner = document.getElementById('predWarning');
    let warnings = [];
    if (company === 'Apple' && opsys !== 'macOS') {
        warnings.push('Apple 原廠硬體通常出廠搭載 macOS；歷史資料庫無 Apple 預載非 macOS 之紀錄。');
    } else if (company !== 'Apple' && opsys === 'macOS') {
        warnings.push('非 Apple 筆電搭載 macOS 屬於黑蘋果 (Hackintosh) 或特殊安裝，歷史資料集無此配置。');
    }

    if (ram >= 32 && cpuType === 'Other Intel') {
        warnings.push('低階處理器 (Other Intel) 搭配 32GB+ 超大記憶體屬於罕見組合。');
    }

    if (warnings.length > 0) {
        warningBanner.style.display = 'block';
        warningBanner.innerHTML = '⚠️ <strong>潛在異常組合提示：</strong><br>' + warnings.join('<br>');
    } else {
        warningBanner.style.display = 'none';
    }
}

