        document.querySelector('input[name="predTouch"][value="0"]').checked = true;
        document.querySelector('input[name="predIps"][value="0"]').checked = true;
        document.getElementById('predRam').value = '4';
        document.getElementById('predSsd').value = '0';
        document.getElementById('predHdd').value = '500';
        document.getElementById('predCpuType').value = 'Intel Core i3';
        document.getElementById('predCpuSpeed').value = 2.0;
