/**
 * 7. 驗證樣本載入至預測器 (Verification Samples)
 */
function renderVerificationSamples(samples) {
    const tbody = document.getElementById('verificationTableBody');
    if (!tbody || !samples) return;
    tbody.innerHTML = '';

    samples.forEach((sample, idx) => {
        const tr = document.createElement('tr');
        
        // Calculate JS simulated price right now to prove exact parity
        const trHtml = `
            <td>#${sample.laptop_id}</td>
            <td><strong>${sample.company}</strong> <small style="color:var(--text-muted)">${sample.product}</small></td>
            <td><span class="badge-tag badge-blue">${sample.type_name}</span></td>
            <td>${sample.ram_gb}GB / ${sample.ssd_gb > 0 ? sample.ssd_gb + 'G SSD' : ''} ${sample.hdd_gb > 0 ? sample.hdd_gb + 'G HDD' : ''}</td>
            <td><strong>€${sample.actual_price.toFixed(2)}</strong></td>
            <td><span style="color:#06b6d4; font-weight:600;">€${sample.py_predicted_price.toFixed(2)}</span></td>
            <td><span class="badge-tag badge-green" id="jsPredSample_${idx}">計算中</span></td>
            <td>
                <button class="preset-chip" onclick="loadSampleIntoPredictor(${idx})" style="padding:4px 8px; font-size:11px;">
                    套用至預測器 ↗
                </button>
            </td>
        `;
        tr.innerHTML = trHtml;
        tbody.appendChild(tr);

        // Immediate compute JS price
        setTimeout(() => {
            const jsPred = computeSpecificPrediction(sample);
            const badge = document.getElementById(`jsPredSample_${idx}`);
            if (badge) {
                const diff = Math.abs(jsPred - sample.py_predicted_price);
                badge.textContent = `€${jsPred.toFixed(2)} (差 €${diff.toFixed(2)})`;
            }
        }, 10);
    });
}

function computeSpecificPrediction(sample) {
    const model = globalData.model_parameters;
    const coefs = model.coefficients;
    let pred = model.intercept;

    const featVals = {
        'Ram_GB': sample.ram_gb,
        'Weight_kg': sample.weight_kg,
        'Inches': sample.inches,
        'PPI': sample.ppi,
        'Cpu_Speed_GHz': sample.cpu_speed_ghz,
        'SSD_GB': sample.ssd_gb,
        'HDD_GB': sample.hdd_gb,
        'Touchscreen': sample.touchscreen,
        'IPS': sample.ips
    };

    const compClean = model.top_companies.includes(sample.company) ? sample.company : 'Other';
    model.ohe_categories.Company_Clean.forEach(c => { featVals[`Company_Clean_${c}`] = (compClean === c) ? 1 : 0; });
    model.ohe_categories.TypeName.forEach(t => { featVals[`TypeName_${t}`] = (sample.type_name === t) ? 1 : 0; });
    model.ohe_categories.Cpu_Type.forEach(cp => { featVals[`Cpu_Type_${cp}`] = (sample.cpu_type === cp) ? 1 : 0; });
    model.ohe_categories.Gpu_Brand.forEach(g => { featVals[`Gpu_Brand_${g}`] = (sample.gpu_brand === g) ? 1 : 0; });
    model.ohe_categories.OpSys_Clean.forEach(o => { featVals[`OpSys_Clean_${o}`] = (sample.opsys === o) ? 1 : 0; });

    model.final_features.forEach(feat => {
        pred += (coefs[feat] || 0) * (featVals[feat] || 0);
    });
    return pred;
}

window.loadSampleIntoPredictor = function(idx) {
    if (!globalData || !globalData.verification_samples) return;
    const s = globalData.verification_samples[idx];

    document.getElementById('predCompany').value = globalData.model_parameters.top_companies.includes(s.company) ? s.company : 'Other';
    document.getElementById('predTypeName').value = s.type_name;
    document.getElementById('predInches').value = s.inches;
    
    // Nearest resolution
    if (s.ppi > 220) {
        document.getElementById('predResolution').value = '3840x2160';
    } else if (s.ppi > 180) {
        document.getElementById('predResolution').value = '2560x1440';
    } else if (s.ppi > 130) {
        document.getElementById('predResolution').value = '1920x1080';
    } else {
        document.getElementById('predResolution').value = '1366x768';
    }

    document.querySelector(`input[name="predTouch"][value="${s.touchscreen}"]`).checked = true;
    document.querySelector(`input[name="predIps"][value="${s.ips}"]`).checked = true;
    document.getElementById('predRam').value = String(s.ram_gb);
    document.getElementById('predSsd').value = String(s.ssd_gb);
    document.getElementById('predHdd').value = String(s.hdd_gb);
    document.getElementById('predCpuType').value = s.cpu_type;
    document.getElementById('predCpuSpeed').value = s.cpu_speed_ghz;
    document.getElementById('predGpuBrand').value = s.gpu_brand;
    document.getElementById('predOpSys').value = s.opsys;
    document.getElementById('predWeight').value = s.weight_kg;

    updatePrediction();

    // Scroll to predictor smoothly
    document.getElementById('section-predictor').scrollIntoView({ behavior: 'smooth' });
};

/**
 * 8. 實際值 vs 預測值 散點圖與殘差圖 (Scatter & Residuals)
 */
function renderScatterAndResiduals(scatterData) {
    if (!scatterData || scatterData.length === 0) return;

    // Scatter Plot
    const scatterCtx = document.getElementById('scatterChart');
    if (scatterCtx) {
        if (scatterChart) scatterChart.destroy();

        const points = scatterData.map(d => ({ x: d.actual, y: d.predicted, info: d }));
        const minVal = 0;
        const maxVal = 4000;

        scatterChart = new Chart(scatterCtx, {
            type: 'scatter',
            data: {
                datasets: [
                    {
                        label: '測試集樣本 (261 筆)',
                        data: points,
                        backgroundColor: 'rgba(6, 182, 212, 0.65)',
                        borderColor: '#06b6d4',
                        borderWidth: 1,
                        pointRadius: 4,
                        pointHoverRadius: 7
                    },
                    {
                        type: 'line',
                        label: '完美預測對角線 (y = x)',
                        data: [{ x: minVal, y: minVal }, { x: maxVal, y: maxVal }],
                        borderColor: 'rgba(255, 255, 255, 0.4)',
                        borderWidth: 1.5,
                        borderDash: [6, 6],
                        pointRadius: 0,
                        fill: false
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: {
                        labels: { color: '#94a3b8' }
                    },
                    tooltip: {
                        callbacks: {
                            label: (ctx) => {
                                const pt = ctx.raw;
                                if (!pt.info) return '完美預測線';
                                return [
                                    `${pt.info.company} ${pt.info.product}`,
                                    `實際價格: €${pt.info.actual.toLocaleString()}`,
                                    `預測價格: €${pt.info.predicted.toLocaleString()}`,
                                    `殘差誤差: €${pt.info.residual > 0 ? '+' : ''}${pt.info.residual.toLocaleString()}`
                                ];
                            }
                        }
                    }
                },
                scales: {
                    x: {
                        title: { display: true, text: '實際售價 (€ Actual)', color: '#94a3b8' },
                        grid: { color: 'rgba(255, 255, 255, 0.05)' },
                        ticks: { color: '#94a3b8' }
                    },
                    y: {
                        title: { display: true, text: '模型預測售價 (€ Predicted)', color: '#06b6d4' },
                        grid: { color: 'rgba(255, 255, 255, 0.05)' },
                        ticks: { color: '#94a3b8' }
                    }
                }
            }
        });
    }

    // Residual Distribution Chart
    const resCtx = document.getElementById('residualChart');
    if (resCtx) {
        if (residualChart) residualChart.destroy();

        // Bin residuals into brackets
        const bins = [-800, -500, -300, -150, 0, 150, 300, 500, 800, 1200];
        const binLabels = ['<-500', '-500~-300', '-300~-150', '-150~0', '0~150', '150~300', '300~500', '500~800', '>800'];
        const binCounts = new Array(binLabels.length).fill(0);

        scatterData.forEach(d => {
            const r = d.residual;
            if (r < -500) binCounts[0]++;
            else if (r < -300) binCounts[1]++;
            else if (r < -150) binCounts[2]++;
            else if (r < 0) binCounts[3]++;
            else if (r < 150) binCounts[4]++;
            else if (r < 300) binCounts[5]++;
            else if (r < 500) binCounts[6]++;
            else if (r < 800) binCounts[7]++;
            else binCounts[8]++;
        });

        residualChart = new Chart(resCtx, {
            type: 'bar',
            data: {
                labels: binLabels,
                datasets: [{
                    label: '殘差分佈筆數 (Residual Count)',
                    data: binCounts,
                    backgroundColor: binLabels.map((l, i) => i === 3 || i === 4 ? 'rgba(16, 185, 129, 0.7)' : 'rgba(14, 165, 233, 0.6)'),
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    borderWidth: 1,
                    borderRadius: 4
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                plugins: {
                    legend: { labels: { color: '#94a3b8' } }
                },
                scales: {
                    x: {
                        title: { display: true, text: '殘差區間 (€: 實際值 - 預測值)', color: '#94a3b8' },
                        grid: { color: 'rgba(255, 255, 255, 0.05)' },
                        ticks: { color: '#94a3b8' }
                    },
                    y: {
                        title: { display: true, text: '樣本數量 (筆)', color: '#94a3b8' },
                        grid: { color: 'rgba(255, 255, 255, 0.05)' },
                        ticks: { color: '#94a3b8' }
                    }
                }
            }
        });
    }
}

/**
 * 頁籤切換事件綁定
 */
function setupEventListeners() {
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.addEventListener('click', () => {
            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));

            btn.classList.add('active');
            const targetId = btn.getAttribute('data-tab');
            const targetEl = document.getElementById(targetId);
            if (targetEl) targetEl.classList.add('active');
        });
    });
}
